{
  "findings": [
    {
      "check_id": "CKV_AWS_115",
      "title": "Environment variable contains sensitive data",
      "resource": "aws_batch_job_definition.pass3",
      "severity": "HIGH",
      "explanation": "Environment variables should not contain sensitive data such as secrets or credentials. In this file, the environment variable 'VARNAME' is hardcoded with a value, which could potentially expose sensitive information."
    }
  ],
  "patched_code": "resource "aws_batch_job_definition" "pass3" {
  name = "tf_test_batch_job_definition"
  type = "container"

  container_properties = jsonencode({
    "command" : ["ls", "-la"],
    "image" : "busybox",
    "memory" : 1024,
    "vcpus" : 1,
    "volumes" : [
      {
        "host" : {
          "sourcePath" : "/tmp"
        },
        "name" : "tmp"
      }
    ],
    "environment" : [],
    "mountPoints" : [
      {
        "sourceVolume" : "tmp",
        "containerPath" : "/tmp",
        "readOnly" : false
      }
    ],
    "ulimits" : [
      {
        "hardLimit" : 1024,
        "name" : "nofile",
        "softLimit" : 1024
      }
    ]
  })
}
",
  "fix_summary": "Removed the hardcoded environment variable 'VARNAME' to prevent potential exposure of sensitive data."
}
